def Target : Prop :=
  ∀ (K : Def1) (F : ArithmeticTheory) [F.RE] [𝗜𝚺₁ ⪯ F],
    Def4 F → F.theory ⊆ K → Def7 F ∈ K → F.theory ⊂ K

